// Characterization tests: pin the HTTP behavior clients see today, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2, pear: 3.5, gold: 60, cheap: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order and returns 201 with id, items, total', async () => {
  const items = [{ sku: 'apple', qty: 3 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 6)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums quantity * unit price across items', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'gold', qty: 1 }] })).json()
  assert.equal(order.total, 64)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(order.total, 3)
})

test('10% discount applies only when total is strictly over 100', async () => {
  assert.equal((await (await post({ items: [{ sku: 'gold', qty: 1 }, { sku: 'apple', qty: 20 }] })).json()).total, 100)
  assert.equal((await (await post({ items: [{ sku: 'apple', qty: 50 }] })).json()).total, 100)
  assert.equal((await (await post({ items: [{ sku: 'apple', qty: 51 }] })).json()).total, 91)
  assert.equal((await (await post({ items: [{ sku: 'gold', qty: 2 }] })).json()).total, 108)
})

test('GET /orders/:id returns a previously created order', async () => {
  const created = await (await post({ items: [{ sku: 'apple', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with {error:"not found"} (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('POST /orders validation errors return 400 {error:"items required"}', async () => {
  const cases = [{}, { items: [] }, { items: 'x' }, { items: null }]
  for (const body of cases) {
    const res = await post(body)
    assert.equal(res.status, 400, JSON.stringify(body))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders with malformed JSON returns 400', async () => {
  const res = await post(null, '{nope')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('POST /orders with empty body returns 400', async () => {
  const res = await post(null, '')
  assert.equal(res.status, 400)
})

test('unknown routes and unsupported methods return 404 {error:"no route"}', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['POST', '/orders/1'], ['GET', '/orders/1/extra']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 1 }] })
  const { id } = await res.json()
  const got = await fetch(`${base}/orders/${id}?x=1`)
  assert.equal((await got.json()).id, id)
})

test('unknown sku (no price) yields a 201 with total 0 serialized from NaN', async () => {
  const res = await post({ items: [{ sku: 'mystery', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})
